function buildStructuredQuestions(rawList, tier, prefix) {
  return rawList.map((row, idx) => {
    const [category, prompt, correctOpt, w1, w2, w3, funFact] = row;
    const correctIndex = idx % 4; // Deterministically distribute across 0 (Red), 1 (Blue), 2 (Amber), 3 (Emerald)
    const wrongs = [w1, w2, w3];
    // Rotate wrongs slightly by idx so distractors vary order too
    const rotatedWrongs = [
      wrongs[idx % 3],
      wrongs[(idx + 1) % 3],
      wrongs[(idx + 2) % 3]
    ];
    const options = [];
    let wPtr = 0;
    for (let slot = 0; slot < 4; slot++) {
      if (slot === correctIndex) {
        options.push(correctOpt);
      } else {
        options.push(rotatedWrongs[wPtr++]);
      }
    }

    return {
      id: `${prefix}_${String(idx + 1).padStart(3, '0')}`,
      tier,
      category,
      prompt,
      options,
      correctIndex,
      funFact
    };
  });
}

function main() {
  const adultQuestions = buildStructuredQuestions(ADULT_RAW, 'ADULT', 'adult');
  const wyattQuestions = buildStructuredQuestions(WYATT_4YO_RAW, 'WYATT_4YO', 'wyatt');
  const emmaQuestions = buildStructuredQuestions(EMMA_3YO_RAW, 'EMMA_3YO', 'emma');

  const allQuestions = [...adultQuestions, ...wyattQuestions, ...emmaQuestions];

  const payload = {
    version: '2.0.0',
    generatedAt: new Date().toISOString(),
    counts: {
      total: allQuestions.length,
      adult: adultQuestions.length,
      wyatt4yo: wyattQuestions.length,
      emma3yo: emmaQuestions.length
    },
    questions: allQuestions
  };

  fs.mkdirSync(path.dirname(OUT_PATH), { recursive: true });
  fs.writeFileSync(OUT_PATH, JSON.stringify(payload, null, 2), 'utf8');
  console.log(
    `[TRIVIA BANK BUILT] ${OUT_PATH} — Total: ${payload.counts.total} (Adult: ${payload.counts.adult}, Wyatt 4YO: ${payload.counts.wyatt4yo}, Emma 3YO: ${payload.counts.emma3yo})`
  );
}

main();
